{% macro replay_q_dup() %}
  {% do run_query("BEGIN") %}

  {% set statement_0 %}
MERGE INTO {{ ref('q_dup') }} AS _target
USING (
  SELECT
    group_id,
    note,
    status,
    _ingested_at,
    _load_id,
    _source_row_id,
    _quality_flags,
