      _evaluated.note,
      _evaluated.status,
      _evaluated._ingested_at,
      _evaluated._load_id,
      _evaluated._source_row_id,
      _evaluated._quality_flags,
      COALESCE(ARRAY_LENGTH(_evaluated._quality_flags, 1), 0) = 0 AS _quality_ok,
      ROW_NUMBER() OVER (PARTITION BY group_id ORDER BY _source_row_id DESC NULLS LAST) AS _w
    FROM (
      SELECT
        _extract.group_id,
        _extract.note,
        _extract.status,
        _extract._ingested_at,
        _extract._load_id,
        _extract._source_row_id,
        CASE
          WHEN _extract._branch_note_coercible
          THEN ARRAY['note_coercible']
          ELSE CAST(ARRAY[] AS TEXT[])
        END AS _quality_flags
      FROM (
        SELECT
          CASE
            WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.group_id'), 'TEXT')
            THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.group_id') AS TEXT)
          END AS group_id,
          CASE
            WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.note'), 'TEXT')
            THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.note') AS TEXT)
          END AS note,
          CASE
            WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.status'), 'TEXT')
            THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.status') AS TEXT)
          END AS status,
          _ingested_at,
          _load_id,
          _source_row_id,
          CASE
            WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.group_id'), 'TEXT')
            THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.group_id') AS TEXT)
          END IS NULL
          AND (
            NOT JSON_EXTRACT_PATH_TEXT(raw, '$.group_id') IS NULL
          ) AS _branch_group_id_coercible,
          CASE
            WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.note'), 'TEXT')
            THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.note') AS TEXT)
          END IS NULL
          AND (
            NOT JSON_EXTRACT_PATH_TEXT(raw, '$.note') IS NULL
          ) AS _branch_note_coercible,
          CASE
            WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.status'), 'TEXT')
            THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.status') AS TEXT)
          END IS NULL
          AND (
            NOT JSON_EXTRACT_PATH_TEXT(raw, '$.status') IS NULL
          ) AS _branch_status_coercible
        FROM {{ ref('q_dup__reject') }}
        WHERE
          resolved_at IS NULL
      ) AS _extract
      WHERE
        NOT COALESCE(
          (
            _extract._branch_group_id_coercible
            OR _extract._branch_status_coercible
            OR (
              NOT _extract.status IN ('open', 'closed')
            )
          ),
          FALSE
        )
    ) AS _evaluated
  ) AS _t
  WHERE
    _w = 1
) AS _replay
ON _target.group_id = _replay.group_id
WHEN MATCHED AND (
  (
    NOT _replay._source_row_id IS NULL AND _target._source_row_id IS NULL
  )
  OR (
    NOT _replay._source_row_id IS NULL
    AND NOT _target._source_row_id IS NULL
    AND _replay._source_row_id > _target._source_row_id
  )
) THEN UPDATE SET
  note = _replay.note,
  status = _replay.status,
  _ingested_at = _replay._ingested_at,
  _load_id = _replay._load_id,
  _source_row_id = _replay._source_row_id,
  _quality_flags = _replay._quality_flags,
  _quality_ok = _replay._quality_ok
WHEN NOT MATCHED THEN INSERT (
