  {% set statement_1 %}
UPDATE {{ ref('q_dup__reject') }} SET resolved_at = CURRENT_TIMESTAMP, last_evaluated_at = CURRENT_TIMESTAMP
WHERE
  resolved_at IS NULL
  AND _source_row_id IN (
